    def setup_method(self):
        options = webdriver.ChromeOptions()
        options.add_argument('ignore-certificate-errors')
        self.driver = webdriver.Chrome(chrome_options=options)
        self.driver.implicitly_wait(waitTime)
        self.URL = emsURL
        self.vars = {}
        self.driver.get(self.URL)
        self.driver.maximize_window()
        self.driver.find_element(By.ID, "name").send_keys(emsUsr)
        self.driver.find_element(By.ID, "passwd").clear()
        self.driver.find_element(By.ID, "passwd").send_keys(emsPwd)
        self.driver.find_element(By.ID, "signin").click()
        WebDriverWait(self.driver, 180).until(EC.visibility_of_element_located((By.ID,"index_t_userName")))
        self.login_time = (datetime.now() + timedelta(minutes = 1)).strftime("%Y-%m-%d %H:%M:%S")
        #Check the tested ontsn count = 1
        self.driver.find_element(By.LINK_TEXT, "Inventory").click()
        WebDriverWait(self.driver, 300).until(EC.visibility_of_element_located((By.LINK_TEXT, "ONT")))
        self.driver.find_element(By.LINK_TEXT, "ONT").click()
        self.driver.find_element(By.CSS_SELECTOR, "#i_action_filter > a").click()
        self.driver.find_element(By.ID, "inventory_allont_clear_btn").click()
        self.driver.find_element(By.ID, "serial_Allont").send_keys(serviceOntSN)
        self.driver.find_element(By.ID, "inventory_allont_btn").click()
        WebDriverWait(self.driver, 300).until(EC.visibility_of_element_located((By.ID, "table_total_data_ont_inventory_div")))
        matchOntCount = self.driver.find_element(By.ID, "table_total_data_ont_inventory_div").text.replace(" Total data","")

    def teardown_method(self):
        #Log out the dutweb page
        logoutDutWeb(self, dutType)
        self.driver.quit()

