    def test_ontACLPrfAdd(self):
        if dutSlotTotal != "0" and serviceOntType == "GPON": return
        deleteServiceWithProfile(self, "$py_TempONTACL")
        deleteServiceWithSn(self, serviceOntSN)
        waitOntIdUpdate(self, serviceOntSN, "Unregistered") 
        #Delete auto_ profile if the table full
        deleteAutoMaxFileIfTableFull(self,"ONT Template",3000)
        deleteAutoMaxFileIfTableFull(self,"ONT ONT Profile",3000)
        deleteAutoMaxFileIfTableFull(self,"ONT ACL Profile",3000-ontACLPrfmaxCount)
        #Delete profile in profile list
        deleteFileIfExisted(self,"ONT Template","$py_TempONTACL")
        deleteFileIfExisted(self,"ONT ONT Profile","$py_ONTONTACL")
        for indPrf in range (ontACLPrfmaxCount):
            deleteFileIfExisted(self,"ONT ACL Profile","$py_ONTACL" + str(indPrf+1))
            #Create ONT ACL profile: "$py_ONTACL"
            createProfile (self, "ONT ACL Profile", "$py_ONTACL" + str(indPrf+1))
            self.driver.find_element(By.XPATH, "//label[@for=\"ont_acl_enable_checkbox\"]").click()
            Select(self.driver.find_element(By.ID, "ont_acl_policy_combobox")).select_by_visible_text("Trust")
            Select(self.driver.find_element(By.ID, "ont_acl_interface_combobox")).select_by_visible_text("Both")
            self.driver.find_element(By.XPATH, "//label[@for=\"ont_acl_count_checkbox\"]").click()
            self.driver.find_element(By.XPATH, "//label[@for=\"ont_acl_log_checkbox\"]").click()
            self.driver.find_element(By.ID, "ont_acl_protocol_text").send_keys(Keys.CONTROL + "a")
            self.driver.find_element(By.ID, "ont_acl_protocol_text").send_keys(Keys.DELETE)
            self.driver.find_element(By.ID, "ont_acl_protocol_text").send_keys(str(indPrf+1))
            self.driver.find_element(By.ID, "ont_acl_srcport_text").send_keys("65535")
            self.driver.find_element(By.ID, "ont_acl_dstport_text").send_keys("1")
            self.driver.find_element(By.ID, "ont_acl_srcip_text").send_keys(Keys.CONTROL + "a")
            self.driver.find_element(By.ID, "ont_acl_srcip_text").send_keys(Keys.DELETE)
